{
  "application": "data-visualization",
  "case_id": "case-ai-three-track-timeline-2010-2024",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "analyst",
    "tone": "narrative, data-dense, polished"
  },
  "goal": [
    {
      "id": "three-track-convergence",
      "insight": "Show the three parallel tracks (research breakthroughs, industry adoption, regulatory action) over 2010–2024, visually emphasizing how their lag gap compresses dramatically around the ChatGPT moment (late 2022)"
    },
    {
      "id": "chatgpt-inflection",
      "insight": "Mark the ChatGPT launch (Nov 2022) as a prominent visual anchor point where all three tracks visibly accelerate or cluster, distinguishing the pre- and post-ChatGPT eras"
    },
    {
      "id": "investment-overlay",
      "insight": "Overlay annual global AI investment figures along the timeline so the viewer can see how capital surges align with milestone clusters on the three tracks"
    },
    {
      "id": "lag-gap-contrast",
      "insight": "Highlight the multi-year gap between research milestones and corresponding regulatory responses in the 2012–2020 period versus the near-simultaneous response in 2023–2024"
    },
    {
      "id": "post-2022-density",
      "insight": "Emphasize the visual density of milestones across all three tracks in the 2023–2024 window compared to the sparser earlier years"
    }
  ]
}

