        --accent-dim: rgba(91, 143, 201, 0.10);
      }
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: var(--font-body);
      background: var(--bg);
      background-image:
        radial-gradient(ellipse at 30% 0%, var(--research-dim) 0%, transparent 55%),
        radial-gradient(ellipse at 80% 90%, var(--investment-dim) 0%, transparent 50%);
      color: var(--text);
      min-height: 100vh;
      overflow-wrap: break-word;
    }

    .page {
      max-width: 1180px;
      margin: 0 auto;
      padding: 48px 32px 80px;
    }

    /* ── Header ───────────────────────────────────── */
    .page-header {
      margin-bottom: 48px;
      border-bottom: 1px solid var(--border-bright);
      padding-bottom: 32px;
    }
    .page-header__eyebrow {
      font-family: var(--font-mono);
      font-size: 11px;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 2.5px;
      color: var(--text-dim);
      margin-bottom: 12px;
    }
    .page-header__title {
      font-family: var(--font-display);
      font-size: clamp(28px, 4vw, 46px);
      font-weight: 800;
      line-height: 1.1;
      color: var(--text-bright);
      letter-spacing: -0.5px;
      margin-bottom: 14px;
    }
    .page-header__subtitle {
      font-size: 16px;
      font-style: italic;
      color: var(--text-dim);
      max-width: 680px;
      line-height: 1.6;
    }

    /* ── KPI row ─────────────────────────────────── */
    .kpi-row {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
      margin-bottom: 40px;
    }
    .kpi-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 18px 20px;
      animation: fadeScale 0.4s ease-out both;
      animation-delay: calc(var(--i, 0) * 0.07s);
    }
    .kpi-card__value {
      font-family: var(--font-display);
      font-size: 30px;
      font-weight: 700;
      line-height: 1;
      margin-bottom: 6px;
    }
    .kpi-card__label {
      font-family: var(--font-mono);
      font-size: 10px;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--text-dim);
    }
    .kpi-card__trend {
      font-family: var(--font-mono);
      font-size: 11px;
      margin-top: 4px;
    }
    .kpi-card--research { border-left: 3px solid var(--research); }
    .kpi-card--industry { border-left: 3px solid var(--industry); }
    .kpi-card--regulatory { border-left: 3px solid var(--regulatory); }
    .kpi-card--investment { border-left: 3px solid var(--investment); }
    .kpi-card--research .kpi-card__value { color: var(--research); }
    .kpi-card--industry .kpi-card__value { color: var(--industry); }
    .kpi-card--regulatory .kpi-card__value { color: var(--regulatory); }
    .kpi-card--investment .kpi-card__value { color: var(--investment); }

    /* ── Legend ──────────────────────────────────── */
    .legend {
      display: flex;
      flex-wrap: wrap;
      gap: 20px;
      align-items: center;
      margin-bottom: 20px;
    }
    .legend__item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-family: var(--font-mono);
      font-size: 11px;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--text-dim);
    }
    .legend__dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      flex-shrink: 0;
    }
    .legend__line {
      width: 20px;
      height: 3px;
      border-radius: 2px;
      flex-shrink: 0;
    }
    .legend__sep {
      width: 1px;
      height: 18px;
      background: var(--border-bright);
    }
    .legend__chatgpt {
      width: 2px;
      height: 14px;
      background: var(--chatgpt);
      flex-shrink: 0;
    }

    /* ── Main chart surface ─────────────────────── */
    .chart-surface {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 24px 24px 20px;
      margin-bottom: 32px;
      overflow: hidden;
    }
    .chart-surface__label {
      font-family: var(--font-mono);
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--text-dim);
      margin-bottom: 16px;
    }

    /* ── Investment bar chart ───────────────────── */
    .investment-chart-wrap {
      margin-bottom: 0;
      height: 120px;
      position: relative;
    }
    .investment-chart-wrap canvas {
      width: 100% !important;
    }

    /* ── SVG Timeline ───────────────────────────── */
    .timeline-wrap {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 24px;
      margin-bottom: 32px;
      overflow-x: auto;
    }
    .timeline-wrap__label {
      font-family: var(--font-mono);
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--text-dim);
      margin-bottom: 16px;
    }
    .timeline-svg-container {
      min-width: 860px;
      position: relative;
    }

    /* ── Lag gap callout ────────────────────────── */
    .callout-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
      margin-bottom: 32px;
    }
    .era-callout {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 20px 24px;
      animation: fadeUp 0.4s ease-out both;
      animation-delay: calc(var(--i, 0) * 0.08s);
    }
    .era-callout__tag {
      font-family: var(--font-mono);
      font-size: 10px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      margin-bottom: 10px;
      display: inline-block;
      padding: 3px 8px;
      border-radius: 4px;
    }
    .era-callout__tag--pre {
      background: var(--research-dim);
      color: var(--research);
    }
    .era-callout__tag--post {
      background: rgba(192, 57, 43, 0.10);
      color: var(--chatgpt);
    }
    .era-callout__title {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 700;
      line-height: 1.2;
      color: var(--text-bright);
      margin-bottom: 8px;
    }
    .era-callout__body {
      font-size: 13px;
      line-height: 1.65;
      color: var(--text-dim);
    }
    .era-callout__stat {
      display: flex;
      align-items: baseline;
      gap: 8px;
      margin-top: 14px;
      padding-top: 12px;
      border-top: 1px solid var(--border);
    }
    .era-callout__stat-val {
      font-family: var(--font-display);
      font-size: 26px;
      font-weight: 700;
    }
    .era-callout__stat-desc {
      font-family: var(--font-mono);
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--text-dim);
    }

    /* ── Density section ────────────────────────── */
    .density-row {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 22px 24px;
      margin-bottom: 32px;
    }
    .density-row__label {
      font-family: var(--font-mono);
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--text-dim);
      margin-bottom: 16px;
    }
    .density-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 8px;
    }
    .density-period {
      text-align: center;
    }
    .density-period__label {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--text-dim);
      margin-bottom: 8px;
    }
    .density-bar-wrap {
      display: flex;
      justify-content: center;
      gap: 3px;
      align-items: flex-end;
      height: 60px;
    }
    .density-bar {
      width: 12px;
      border-radius: 3px 3px 0 0;
      transition: opacity 0.2s;
    }
    .density-period__total {
      font-family: var(--font-display);
      font-size: 18px;
      font-weight: 700;
      margin-top: 6px;
    }
    .density-period__sub {
      font-family: var(--font-mono);
      font-size: 9px;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--text-dim);
    }

    /* ── Data source footer ─────────────────────── */
    .footer {
      border-top: 1px solid var(--border);
      padding-top: 20px;
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--text-dim);
      line-height: 1.7;
    }

    /* ── Animations ─────────────────────────────── */
    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(14px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes fadeScale {
      from { opacity: 0; transform: scale(0.94); }
      to   { opacity: 1; transform: scale(1); }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (max-width: 800px) {
      .kpi-row { grid-template-columns: 1fr 1fr; }
      .callout-row { grid-template-columns: 1fr; }
      .density-grid { grid-template-columns: repeat(3, 1fr); }
      .page { padding: 24px 16px 48px; }
    }
  </style>
</head>
<body>
<div class="page">

  <!-- Header -->
  <header class="page-header">
    <p class="page-header__eyebrow">AI Convergence Analysis · 2010–2024</p>
    <h1 class="page-header__title">Three Tracks, One Inflection</h1>
    <p class="page-header__subtitle">How research breakthroughs, industry adoption, and regulatory action converged — and how a single product launch compressed years of lag into months.</p>
  </header>

  <!-- KPI Row -->
  <div class="kpi-row">
    <div class="kpi-card kpi-card--research" style="--i:0">
      <div class="kpi-card__value">22</div>
      <div class="kpi-card__label">Research Milestones</div>
      <div class="kpi-card__trend" style="color:var(--research)">2011–2024</div>
    </div>
    <div class="kpi-card kpi-card--industry" style="--i:1">
      <div class="kpi-card__value">21</div>
      <div class="kpi-card__label">Industry Events</div>
      <div class="kpi-card__trend" style="color:var(--industry)">Products &amp; investment</div>
    </div>
    <div class="kpi-card kpi-card--regulatory" style="--i:2">
      <div class="kpi-card__value">19</div>
      <div class="kpi-card__label">Regulatory Actions</div>
      <div class="kpi-card__trend" style="color:var(--regulatory)">Lag compressed post-2022</div>
    </div>
    <div class="kpi-card kpi-card--investment" style="--i:3">
      <div class="kpi-card__value">$110B</div>
      <div class="kpi-card__label">AI Investment 2024</div>
      <div class="kpi-card__trend" style="color:var(--investment)">vs $1.3B in 2010</div>
    </div>
  </div>

  <!-- Legend -->
  <div class="legend" style="margin-bottom:12px;">
    <div class="legend__item"><span class="legend__dot" style="background:var(--research)"></span>Research</div>
    <div class="legend__item"><span class="legend__dot" style="background:var(--industry)"></span>Industry</div>
    <div class="legend__item"><span class="legend__dot" style="background:var(--regulatory)"></span>Regulatory</div>
    <div class="legend__sep"></div>
    <div class="legend__item"><span class="legend__chatgpt"></span>ChatGPT Launch (Nov 2022)</div>
    <div class="legend__sep"></div>
    <div class="legend__item"><span class="legend__line" style="background:var(--investment)"></span>Annual AI Investment (bars)</div>
  </div>

  <!-- Investment bar chart -->
  <div class="chart-surface">
    <div class="chart-surface__label">Global Private AI Investment · Billion USD</div>
    <div class="investment-chart-wrap">
      <canvas id="investChart"></canvas>
    </div>
  </div>

  <!-- SVG Timeline -->
  <div class="timeline-wrap">
    <div class="timeline-wrap__label">Three-Track Milestone Timeline · 2010–2024 &nbsp;|&nbsp; Scroll horizontally if needed</div>
    <div class="timeline-svg-container">
      <svg id="timelineSvg" xmlns="http://www.w3.org/2000/svg" width="100%" style="display:block;"></svg>
    </div>
  </div>

  <!-- Era callouts: lag gap -->
  <div class="callout-row">
    <div class="era-callout" style="--i:0; border-left: 3px solid var(--research);">
      <span class="era-callout__tag era-callout__tag--pre">Pre-ChatGPT Era · 2012–2022</span>
      <div class="era-callout__title">The Multi-Year Lag Gap</div>
      <div class="era-callout__body">Research milestones like AlexNet (2012), GANs (2014), and the Transformer (2017) each preceded meaningful regulatory response by 4–6 years. Policy moved in 3-year planning cycles while AI advanced at exponential pace.</div>
      <div class="era-callout__stat">
        <span class="era-callout__stat-val" style="color:var(--research)">4–6 yrs</span>
        <span class="era-callout__stat-desc">Avg research-to-regulation lag<br>for 2012–2020 milestones</span>
      </div>
    </div>
    <div class="era-callout" style="--i:1; border-left: 3px solid var(--chatgpt);">
      <span class="era-callout__tag era-callout__tag--post">Post-ChatGPT Era · 2023–2024</span>
      <div class="era-callout__title">Near-Simultaneous Response</div>
      <div class="era-callout__body">ChatGPT's Nov 2022 launch triggered immediate regulatory action: Italy banned it in March 2023; US Senate hearings followed in May; Biden's Executive Order came in October 2023 — all within 12 months of the launch.</div>
      <div class="era-callout__stat">
        <span class="era-callout__stat-val" style="color:var(--chatgpt)">&lt; 12 mo</span>
        <span class="era-callout__stat-desc">Research-to-regulation compression<br>for 2023–2024 milestones</span>
      </div>
    </div>
  </div>

  <!-- Density section -->
  <div class="density-row">
    <div class="density-row__label">Milestone Density by Period · All Three Tracks Combined</div>
    <div class="density-grid" id="densityGrid"></div>
  </div>

  <!-- Footer -->
  <footer class="footer">
    Sources: Stanford HAI AI Index · CB Insights · Official government/EU publications · Company announcements<br>
    Investment figures are estimated annual global private AI investment (2024 = partial-year projection). Milestone dates reflect earliest public announcement month.
  </footer>

</div>

<script src="/app/libs/chart.js"></script>
<script>
