    { id:'industry',   label:'Industry',   color: C.industry,   data: industry,   rows: 3 },
    { id:'regulatory', label:'Regulatory', color: C.regulatory, data: regulatory, rows: 2 },
  ];

  // Compute width dynamically
  const containerW = Math.max(860, container.offsetWidth || 1000);
  const chartW = containerW - 48; // padding
  const plotW  = chartW - marginLeft - marginRight;

  function xPos(year, month) {
    const frac = (year + (month - 0.5) / 12 - START_YEAR) / (END_YEAR + 1 - START_YEAR);
    return marginLeft + frac * plotW;
  }

  // Assign row within track to avoid overlap
  function assignRows(data, rows, trackStartYear) {
    const slots = Array.from({length: rows}, () => -Infinity);
    return data.map(d => {
      const x = xPos(d.year, d.month);
      let bestRow = 0;
      let bestSlack = -Infinity;
      for (let r = 0; r < rows; r++) {
        const slack = x - slots[r];
        if (slack > bestSlack) { bestSlack = slack; bestRow = r; }
      }
      slots[bestRow] = x + 6;
      return { ...d, row: bestRow };
    });
  }

  // Layout tracks vertically
  let totalH = marginTop + 28; // year labels
  const trackLayouts = tracks.map(t => {
    const y0 = totalH + trackHeaderH;
    const placed = assignRows(t.data, t.rows, START_YEAR);
    const trackH = t.rows * rowHeight + trackPad * 2;
    totalH += trackHeaderH + trackH + 8;
    return { ...t, placed, y0, trackH };
  });
  totalH += 10;

  svg.setAttribute('viewBox', `0 0 ${chartW} ${totalH}`);
  svg.setAttribute('height', totalH);

  let html = '';

  // ── Background regions ──────────────────────────────────────────────────
  // Pre-ChatGPT: 2010 to Nov 2022
  const chatGPT_x = xPos(2022, 11);
  const x0 = marginLeft;
  html += `<rect x="${x0}" y="${marginTop}" width="${chatGPT_x - x0}" height="${totalH - marginTop - 10}"
    fill="${isDark ? 'rgba(255,245,200,0.015)' : 'rgba(30,26,20,0.018)'}" rx="0"/>`;
  // Post-ChatGPT region
  const endX = marginLeft + plotW;
  html += `<rect x="${chatGPT_x}" y="${marginTop}" width="${endX - chatGPT_x}" height="${totalH - marginTop - 10}"
    fill="${isDark ? 'rgba(192,57,43,0.07)' : 'rgba(192,57,43,0.04)'}" rx="0"/>`;

  // ── Year axis ──────────────────────────────────────────────────────────
  // Tick grid lines
  YEARS.forEach(yr => {
    const x = xPos(yr, 1);
    html += `<line x1="${x}" y1="${marginTop}" x2="${x}" y2="${totalH - 10}"
      stroke="${isDark ? 'rgba(255,245,200,0.07)' : 'rgba(30,26,20,0.07)'}" stroke-width="1"/>`;
    html += `<text x="${x + (plotW / 14 / 2)}" y="${marginTop - 8}" text-anchor="middle"
      font-family="'IBM Plex Mono',monospace" font-size="11" fill="${C.textDim}">${yr}</text>`;
  });

  // ── ChatGPT anchor line ────────────────────────────────────────────────
  html += `<line x1="${chatGPT_x}" y1="${marginTop}" x2="${chatGPT_x}" y2="${totalH - 10}"
    stroke="${C.chatgpt}" stroke-width="2" stroke-dasharray="6 3"/>`;
  html += `<rect x="${chatGPT_x - 40}" y="${marginTop}" width="80" height="16" rx="3"
    fill="${C.chatgpt}"/>`;
  html += `<text x="${chatGPT_x}" y="${marginTop + 11}" text-anchor="middle"
    font-family="'IBM Plex Mono',monospace" font-size="9" font-weight="600" fill="white">ChatGPT Nov '22</text>`;

  // ── Era labels ─────────────────────────────────────────────────────────
  const preMidX = marginLeft + (chatGPT_x - marginLeft) / 2;
  const postMidX = chatGPT_x + (endX - chatGPT_x) / 2;
  html += `<text x="${preMidX}" y="${marginTop + 30}" text-anchor="middle"
    font-family="'IBM Plex Mono',monospace" font-size="9" letter-spacing="1.5" text-transform="uppercase"
    fill="${isDark ? 'rgba(255,245,200,0.25)' : 'rgba(30,26,20,0.22)'}">PRE-CHATGPT ERA</text>`;
  html += `<text x="${postMidX}" y="${marginTop + 30}" text-anchor="middle"
    font-family="'IBM Plex Mono',monospace" font-size="9" letter-spacing="1.5"
    fill="${isDark ? 'rgba(192,57,43,0.5)' : 'rgba(192,57,43,0.4)'}">POST-CHATGPT ERA</text>`;

  // ── Lag gap annotations ────────────────────────────────────────────────
  // AlexNet 2012 → first real regulation 2018 (~6yr)
  const alexX = xPos(2012, 9);
  const gdprX = xPos(2018, 4);
  const lagY  = totalH - 24;
  html += `<line x1="${alexX}" y1="${lagY}" x2="${gdprX}" y2="${lagY}"
    stroke="${C.research}" stroke-width="1.5" marker-end="url(#arrowB)" marker-start="url(#arrowF)" opacity="0.6"/>`;
  html += `<text x="${(alexX + gdprX) / 2}" y="${lagY - 5}" text-anchor="middle"
    font-family="'IBM Plex Mono',monospace" font-size="9" fill="${C.research}" opacity="0.7">~6yr lag</text>`;

  // ── Arrow markers ──────────────────────────────────────────────────────
  html = `<defs>
    <marker id="arrowB" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
      <path d="M0,0 L6,3 L0,6 Z" fill="${C.research}" opacity="0.6"/>
    </marker>
    <marker id="arrowF" markerWidth="6" markerHeight="6" refX="1" refY="3" orient="auto-start-reverse">
      <path d="M0,0 L6,3 L0,6 Z" fill="${C.research}" opacity="0.6"/>
    </marker>
  </defs>` + html;

  // ── Tracks ─────────────────────────────────────────────────────────────
  trackLayouts.forEach(t => {
    // Track header band
    html += `<rect x="0" y="${t.y0 - trackHeaderH}" width="${chartW}" height="${trackHeaderH}"
      fill="${isDark ? 'rgba(255,245,200,0.04)' : 'rgba(30,26,20,0.04)'}"/>`;
    html += `<rect x="0" y="${t.y0 - trackHeaderH}" width="4" height="${trackHeaderH}" fill="${t.color}"/>`;
    html += `<text x="10" y="${t.y0 - trackHeaderH + 14}" font-family="'IBM Plex Mono',monospace"
      font-size="10" font-weight="600" letter-spacing="1.5" fill="${t.color}"
      text-transform="uppercase">${t.label.toUpperCase()}</text>`;

    // Track body background
    const bodyY = t.y0;
    const bodyH = t.trackH;
    html += `<rect x="${marginLeft}" y="${bodyY}" width="${plotW}" height="${bodyH}"
      fill="${isDark ? 'rgba(255,255,255,0.01)' : 'rgba(0,0,0,0.008)'}" rx="2"/>`;

    // Track label in margin
    html += `<text x="${marginLeft - 8}" y="${bodyY + bodyH/2 + 4}" text-anchor="end"
      font-family="'IBM Plex Mono',monospace" font-size="9" fill="${t.color}" opacity="0.7"
      transform="rotate(-90, ${marginLeft - 8}, ${bodyY + bodyH/2})">${t.label}</text>`;

    // Milestone dots and labels
    t.placed.forEach(d => {
      const x = xPos(d.year, d.month);
      const rowY = bodyY + trackPad + d.row * rowHeight + rowHeight / 2;
      const isPost = d.year > 2022 || (d.year === 2022 && d.month === 11);
      const dotColor = isPost ? (isDark ? t.color : t.color) : t.color;
      const dotR = isPost ? 5.5 : 4;
      const opacity = isPost ? 1 : 0.78;

      // Connector line from dot to baseline
      html += `<line x1="${x}" y1="${rowY}" x2="${x}" y2="${bodyY + bodyH}"
        stroke="${t.color}" stroke-width="1" opacity="0.18"/>`;

      // Dot
      html += `<circle cx="${x}" cy="${rowY}" r="${dotR}"
        fill="${dotColor}" opacity="${opacity}" stroke="${isDark ? '#1c1a12' : '#fff'}" stroke-width="1.5"/>`;

      // Label
      const labelX = x + 7;
      const labelY = rowY + 4;
      const shortLabel = d.event.length > 32 ? d.event.slice(0, 30) + '…' : d.event;
      const yearLabel = `${d.year}`;
      html += `<text x="${labelX}" y="${labelY - 8}" font-family="'IBM Plex Mono',monospace"
        font-size="8" fill="${t.color}" opacity="0.6">${yearLabel}</text>`;
      html += `<text x="${labelX}" y="${labelY}" font-family="'IBM Plex Sans',system-ui,sans-serif"
        font-size="9.5" fill="${C.text}" opacity="${isPost ? 1 : 0.75}">${shortLabel}</text>`;
    });
  });

  svg.innerHTML = html;
})();

// ── Density section ───────────────────────────────────────────────────────────
(function () {
  const periods = [
    {label:'2010–2012', years:[2010,2011,2012]},
    {label:'2013–2016', years:[2013,2014,2015,2016]},
    {label:'2017–2019', years:[2017,2018,2019]},
    {label:'2020–2022', years:[2020,2021,2022]},
    {label:'2023–2024', years:[2023,2024]},
  ];

  function countIn(data, years) { return data.filter(d => years.includes(d.year)).length; }

  const allCounts = periods.map(p => ({
    r: countIn(research, p.years),
    i: countIn(industry, p.years),
    g: countIn(regulatory, p.years),
    total: countIn(research, p.years) + countIn(industry, p.years) + countIn(regulatory, p.years),
  }));
  const maxTotal = Math.max(...allCounts.map(c => c.total));
  const maxH = 52;

  const container = document.getElementById('densityGrid');
  const cs2 = getComputedStyle(document.documentElement);
  const resColor = cs2.getPropertyValue('--research').trim();
  const indColor = cs2.getPropertyValue('--industry').trim();
  const regColor = cs2.getPropertyValue('--regulatory').trim();

  periods.forEach((p, i) => {
    const c = allCounts[i];
    const scale = c.total / maxTotal;
    const rH = Math.max(2, (c.r / c.total) * scale * maxH);
    const iH = Math.max(2, (c.i / c.total) * scale * maxH);
    const gH = Math.max(2, (c.g / c.total) * scale * maxH);
    const isPost = i === 4;

    const div = document.createElement('div');
    div.className = 'density-period';
    div.innerHTML = `
      <div class="density-period__label">${p.label}</div>
      <div class="density-bar-wrap">
        <div class="density-bar" style="height:${rH}px;background:${resColor};opacity:${isPost?1:0.7}"></div>
        <div class="density-bar" style="height:${iH}px;background:${indColor};opacity:${isPost?1:0.7}"></div>
        <div class="density-bar" style="height:${gH}px;background:${regColor};opacity:${isPost?1:0.7}"></div>
      </div>
      <div class="density-period__total" style="color:${isPost ? 'var(--chatgpt)' : 'var(--text)'}">
        ${c.total}
      </div>
      <div class="density-period__sub">milestones</div>
    `;
    container.appendChild(div);
  });
})();
</script>
